namespace hanmo::resident {namespace {
using Result=Outcome<std::optional<DecisionProposal>>;
const PersonalAppointmentAttendancePolicy* configured(const VisitAppointmentAttendanceRead& r,const VisitAppointmentAttendanceCatalog& c,const VisitAppointmentOffered& source){if(std::find(c.invitation_policy_ids.begin(),c.invitation_policy_ids.end(),source.policy_id)==c.invitation_policy_ids.end())return nullptr;const auto* policy=visit_appointment_policy(r.invitations,source.policy_id);if(!policy)return nullptr;for(const auto& p:r.original_attendance.policies)if(p.appointment_policy_id==policy->appointment_policy_id)return &p;return nullptr;}
// 终结必须是本人共同参加的真实会面/取消；不查询尚未发生的另一端答复或对方今日位置。
bool terminal(const VisitAppointmentMeetingState& s,const StableId& id){for(const auto& r:s.cancelled.rows())if(r.second.invitation_fact_id==id)return true;for(const auto& r:s.finished.rows())if(r.second.invitation_fact_id==id)return true;return false;}
Result waiting(DecisionProposal p,const StableId& code){auto& next=const_cast<DirectorTransition&>(*p.transition);p.command.reset();next.phase=PlanPhase::waiting;next.wait_reason=code;return {true,std::move(p),{}};}
}
Status validate_visit_appointment_attendance_sources(const VisitAppointmentAttendanceRead&r,const VisitAppointmentAttendanceCatalog&catalog){
 auto valid=validate_visit_appointment_attendance_catalog(catalog,r.invitations,r.original_attendance,r.appointments);if(!valid.ok)return valid;
 if(r.state.version==1&&r.meetings.version==1)return r.exact?common_failure("VisitAppointmentAttendanceLegacyExactMismatch",{},ErrorKind::internal):common_success();
 if(!r.exact)return common_failure("VisitAppointmentAttendanceExactReadRequired",{},ErrorKind::unsupported_capability);const auto&x=*r.exact;const auto&life=x.invitation_life;
 if(&x.common!=&r.common||&x.interaction!=&r.interaction||&x.catalog!=&r.appointments||&x.invitations!=&r.state||&x.state!=&r.meetings||&life.common!=&r.common||&life.catalog!=&r.invitations||&life.state!=&r.state||&life.meetings!=&r.meetings||!x.definitions.common)return common_failure("VisitAppointmentAttendanceCandidateMismatch",{},ErrorKind::internal);
 valid=validate_visit_appointment_original_sources(r.common,*x.definitions.common,life.messages,life.message_catalog,x.catalog,x.personal,x.definitions,r.invitations,r.state,x.invitation_history,life.ordinary);if(!valid.ok)return valid;
 return validate_visit_appointment_meeting_time2(x);
}
Result propose_visit_appointment_attendance(const VisitAppointmentAttendanceRead& r,const VisitAppointmentAttendanceCatalog& catalog,const TravelCatalog& travel,const KnownSubjectView& view,const DecisionProposal& original){
 auto valid=validate_visit_appointment_attendance_sources(r,catalog);if(!valid.ok)return {false,{},valid.error};const auto& c=r.common;
 if(!original.transition||original.subject_id!=view.actor_id||view.subject.kind!=SubjectKind::actor||view.subject.id!=view.actor_id||view.tick!=c.tick()||view.revision!=c.revision()||original.transition->expected_revision!=c.revision())return {false,{},common_failure("InvalidVisitAppointmentAttendanceSource",view.actor_id).error};
 if(view.actor_id==c.state().metadata.player_actor_id||original.transition->pending_life_action_id)return {true,std::nullopt,{}};
 for(const auto& row:r.tasks.tasks.rows())if(row.second.assignee==view.actor_id&&(row.second.status=="accepted"||row.second.status=="active"||row.second.status=="in_progress"||row.second.status=="ready"||row.second.status=="settling"))return {true,std::nullopt,{}};
 std::optional<WorldMoment> actual;if(r.exact){auto now=r.exact->clock.read_current_moment();if(!now.ok)return {false,{},now.error};if(now.value.half_day_tick!=c.tick())return {false,{},common_failure("StaleVisitAppointmentProposalClock",view.actor_id,ErrorKind::internal).error};actual=std::move(now.value);}
 const VisitAppointmentOffered* selected=nullptr;
 for(const auto& row:r.state.offered.rows()){const auto& promise=row.second;if(promise.terms.inviter_actor_id!=view.actor_id||promise.contact.actor_id!=view.actor_id)continue;const auto* p=configured(r,catalog,promise);if(actual){auto admitted=calendar_deadline_accepts(promise.terms.latest_tick,true,*actual);if(!admitted.ok)return {false,{},admitted.error};if(!admitted.value)continue;}if(!p||c.tick()>promise.terms.latest_tick||c.tick()<std::max<Integer>(0,promise.terms.earliest_tick-p->depart_before_ticks)||terminal(r.meetings,promise.fact_id)||std::any_of(r.state.life_sources.rows().begin(),r.state.life_sources.rows().end(),[&](const auto&life){return life.second.invitation_fact_id==promise.fact_id;}))continue;if(!selected||promise.terms.earliest_tick<selected->terms.earliest_tick)selected=&promise;}
 if(!selected)return {true,std::nullopt,{}};
 DecisionProposal p=original;p.transition=checkpoint_make_shared<DirectorTransition>(*original.transition);p.command.reset();p.reason_fact_id=selected->fact_id;auto& next=const_cast<DirectorTransition&>(*p.transition);next.template_id=personal_appointment_attendance_template;next.goal_ref=selected->fact_id;next.commitment_ids={selected->fact_id};next.current_action_id.reset();next.next_step_index=0;next.wait_reason.clear();if(c.tick()==INT64_MAX)return {false,{},common_failure("VisitAppointmentAttendanceTickOverflow").error};next.next_review_tick=std::min(next.next_review_tick,c.tick()+1);
 const auto* actor=c.actor(view.actor_id);if(!actor||!actor->alive||!actor->available||!view.alive||!view.available)return waiting(std::move(p),"VisitAppointmentActorUnavailable");if(!actor->action_id.empty()||!view.current_action_id.empty()){if(!actor->action_id.empty())next.current_action_id=actor->action_id;return waiting(std::move(p),"VisitAppointmentExistingAction");}
 bool busy=view.interaction_busy;for(const auto& s:r.interaction.interactions)if(s.actor_id==view.actor_id||s.context.provider_actor_id==view.actor_id)busy=true;if(busy)return waiting(std::move(p),"VisitAppointmentExistingInteraction");const auto* members=c.members(view.actor_id);if(!members||members->size()!=1||members->front()!=view.actor_id||!std::holds_alternative<SettlementLocation>(actor->location))return waiting(std::move(p),"VisitAppointmentIndependentTravelRequired");
 auto location=c.resolved_location(view.actor_id);const auto* here=location.ok?std::get_if<SettlementLocation>(&location.value):nullptr;if(!here||here->place_id!=view.place_id||here->settlement_id!=view.settlement_id)return {false,{},common_failure("VisitAppointmentKnownLocationMismatch",view.actor_id).error};
 if(view.place_id==selected->terms.place_id)return waiting(std::move(p),c.tick()<selected->terms.earliest_tick?"VisitAppointmentWindowNotOpen":"VisitAppointmentAwaitingOriginalParticipant");p.command=director_move_toward(travel,view,selected->terms.place_id);if(!p.command)return waiting(std::move(p),"VisitAppointmentRouteUnavailable");next.phase=PlanPhase::delivering;next.next_step_index=1;return {true,std::move(p),{}};
}
Status wake_visit_appointment_attendance(const VisitAppointmentAttendanceRead& r,const VisitAppointmentAttendanceCatalog& catalog,const DirectorCatalog& director,DirectorState& state){if(state.subject2)return common_failure("TypedAppointmentWakeOwnerRequired",{},ErrorKind::unsupported_capability);auto valid=validate_visit_appointment_attendance_catalog(catalog,r.invitations,r.original_attendance,r.appointments);if(!valid.ok)return valid;const auto tick=r.common.tick();for(const auto& row:r.state.offered.rows()){const auto& promise=row.second;const auto& actor=promise.terms.inviter_actor_id;const auto* p=configured(r,catalog,promise);if(!p||actor==r.common.state().metadata.player_actor_id||promise.contact.actor_id!=actor||tick>promise.terms.latest_tick||terminal(r.meetings,promise.fact_id)||!director_subject_active(state,actor))continue;const auto* behavior=director_policy(state,director,actor);auto* schedule=state.schedules.find(actor);if(!behavior||!schedule||std::none_of(behavior->templates.begin(),behavior->templates.end(),[](DirectorTemplate t){return static_cast<Integer>(t)==personal_appointment_attendance_template_number;}))continue;Integer next=std::max(tick,std::max<Integer>(0,promise.terms.earliest_tick-p->depart_before_ticks));if(schedule->last_decision_tick>=tick){if(tick==INT64_MAX)return common_failure("VisitAppointmentAttendanceTickOverflow");next=std::max(next,tick+1);}if(next>promise.terms.latest_tick||next>=schedule->next_tick)continue;schedule->next_tick=next;if(auto* plan=state.plans.find(actor))plan->next_review_tick=next;if(std::find(schedule->wake_reasons.begin(),schedule->wake_reasons.end(),"VisitAppointmentCommitment")==schedule->wake_reasons.end())schedule->wake_reasons.push_back("VisitAppointmentCommitment");}return common_success();}
bool visit_appointment_attendance_goal(const StableId& id){return id.rfind(StableId{visit_appointment_offered_kind}+":",0)==0;}
Status validate_visit_appointment_attendance_plan(const CommonStore& common,const VisitAppointmentState& state,const VisitAppointmentAttendanceCatalog* catalog,const FinitePlan& plan){if(!visit_appointment_attendance_goal(plan.goal_ref))return common_success();const auto* source=state.offered.find(plan.goal_ref);const auto* head=common.state().facts.find(plan.goal_ref);if(!catalog||catalog->version!=1||!source||!head||head->id!=source->fact_id||head->kind!=visit_appointment_offered_kind||head->domain!=visit_appointment_module||!visit_appointment_detail::serial(source->fact_id,visit_appointment_offered_kind,common.state().next_instance_id)||std::find(catalog->invitation_policy_ids.begin(),catalog->invitation_policy_ids.end(),source->policy_id)==catalog->invitation_policy_ids.end()||plan.template_id!=personal_appointment_attendance_template||plan.subject.kind!=SubjectKind::actor||source->terms.inviter_actor_id!=plan.subject.id||source->contact.actor_id!=plan.subject.id||plan.commitment_ids!=std::vector<StableId>{source->fact_id}||plan.step_index<0||plan.step_index>1)return common_failure("InvalidVisitAppointmentAttendancePlan",plan.subject.id);return common_success();}
}
